# Monotonic stack: "next greater element" for every index.
# Stack holds INDICES, values decreasing from bottom to top.
result = [0] * len(nums)
stack = []
for i, x in enumerate(nums):
    while stack and nums[stack[-1]] < x:
        j = stack.pop()       # x is j's next greater element
        result[j] = i - j
    stack.append(i)
# anything left never found a greater element

