class MinStack:
    def __init__(self):
        self.stack = []
        self.min_stack = []  # parallel min tracking

    def push(self, val):
        self.stack.append(val)
        curr_min = min(val, self.min_stack[-1] if self.min_stack else val)
        self.min_stack.append(curr_min)

    def pop(self):
        self.stack.pop()
        self.min_stack.pop()

    def top(self):
        return self.stack[-1]

    def getMin(self):
        return self.min_stack[-1]

