var generateParenthesis = function(n) {
    const result = [];
    const backtrack = (cur, open, close) => {
        if (cur.length === 2 * n) { result.push(cur); return; }
        if (open < n) backtrack(cur + '(', open + 1, close);
        if (close < open) backtrack(cur + ')', open, close + 1);
    };
    backtrack('', 0, 0);
    return result;
};

