var carFleet = function(target, position, speed) {
    const cars = position.map((p, i) => [p, (target - p) / speed[i]])
        .sort((a, b) => b[0] - a[0]);
    let fleets = 0, curTime = 0;
    for (const [_, time] of cars) {
        if (time > curTime) { fleets++; curTime = time; }
    }
    return fleets;
};

